config.script:
// laudo_liberacao_automatica — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Gatilho: o exame mudou de estado (evento `exames.exame_estado_alterado`) e o filtro do gatilho só deixa passar
// `estado = laudado` (o laudo foi ligado ao exame). O evento traz só ids: `subject.exame_id`, `subject.cliente_id`
// e `subject.venda_item_id` (pode vir vazio: exame pedido pelo médico, sem venda).
//
// Ação: pede ao serviço de exames para LIBERAR o resultado ao paciente (`liberar_laudo`), mandando SÓ o id do
// exame. Libera SEM a revisão da médica. Quem decide se pode é o serviço de exames, pelo campo "Liberação
// automática" do TIPO de exame — este agente não tem lista de tipos. Recusas normais (não são erro):
//   - TIPO_SEM_LIBERACAO_AUTOMATICA: o tipo espera a revisão da médica;
//   - SEM_RESULTADO: o exame ainda não tem resultado;
//   - LAUDO_EXIGIDO: a clínica exige o laudo e ele ainda não está ligado.
// Já liberado antes → o serviço responde sucesso sem mudar nada (rodar de novo é seguro).
//
// A liberação dispara o aviso ao paciente "há um resultado novo no portal" (time `laudo-aviso`, se instalado).
//
// Falha visível (anti falso-verde): qualquer outra resposta (erro, exame não encontrado, serviço fora) sai com
// log WARNING e `acao_bloqueada` no resumo — nunca como "liberado".
// Sem dado pessoal no log/resumo: só o id do exame e o código da recusa.
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var RECUSAS_NORMAIS = { TIPO_SEM_LIBERACAO_AUTOMATICA: true, SEM_RESULTADO: true, LAUDO_EXIGIDO: true };
var sub = (event && event.subject) || {};
var ps = (event && event.payload_safe) || {};
var exameId = sub.exame_id ? String(sub.exame_id) : '';

// Defesa: o filtro do gatilho já garante `laudado`; outro estado (gatilho editado) não libera nada.
if (String(ps.estado || '') !== 'laudado') {
  result({ skip: 'estado_alheio' });
  return { skip: 'estado_alheio' };
}
if (!exameId) {
  log('laudo_liberacao_automatica: evento sem exame — nada a liberar');
  result({ skip: 'sem_exame' });
  return { skip: 'sem_exame' };
}

var r = call('liberar_laudo', { exame_id: exameId });
if (r && r.ok) {
  var b = (r.body && r.body.data !== undefined) ? r.body.data : r.body;
  var origem = (b && b.laudo_origem) || null;
  log('laudo_liberacao_automatica: resultado liberado ao paciente (exame ' + exameId + ')');
  result({ liberado: true, laudo_origem: origem });
  return { ok: true, liberado: true };
}

var http = (r && r.status_code) || null;
var detail = (r && r.body && r.body.detail) || null;
var codigo = (detail && typeof detail === 'object' && detail.codigo) ? String(detail.codigo) : null;
if (http === 409 && codigo && RECUSAS_NORMAIS[codigo]) {
  log('laudo_liberacao_automatica: não liberado (' + codigo + ') — segue o fluxo normal da clínica');
  result({ skip: codigo, liberado: false });
  return { skip: codigo };
}

log('laudo_liberacao_automatica: FALHA ao liberar (exame ' + exameId + ', HTTP ' + (http || '?') +
  (codigo ? ', ' + codigo : '') + ')', 'warning');
result({ acao_bloqueada: true, etapa: 'liberar_laudo', http: http, codigo: codigo, liberado: false });
return { ok: false, erro: 'liberar_falhou', http: http, codigo: codigo };
